Rules.InvariantScript:
UpdateContext({CurrentUser:User().FullName});
Reset(ddlResidentYear_all);
Reset(ddlResidentName_all);

UpdateContext({
    ctxStartDate: DateAdd(Today(), -30),
    ctxEndDate: Today()
});
Reset(dpStart_all);
Reset(dpEnd_all);

// Clear any stale HTML when user enters the screen
Set(varHtml_all, Blank());
Set(varHtml_attendingOnly, Blank());
Set(varHtml_final, Blank());
Set(varHasGenerated, false);

//Office365.SendEmail(User().Email, "Feedback Report for " & ddlResidentYear_all.SelectedText.Value & "-Year Resident, " & ddlResidentName_all.SelectedText.ResidentName, html_all.HtmlText, {IsHtml: true, Importance: FontWeight.Normal});

If(
    IsBlank(varHtml_final),
    Notify("Please click Generate to build the report before sending.", NotificationType.Warning, 2000),
    // else: proceed to send
    Office365.SendEmail(
        User().Email,
        "Resident Feedback Summary from All Attending",
        html_all.HtmlText, { IsHtml: true });
    Notify("Email sent.", NotificationType.Success, 1500)
);
